node << 'ENDSCRIPT'
import('./packages/frai-core/src/eval/index.js').then(Eval => {
  return import('./packages/frai-core/src/eval/reporters.js').then(reporters => {
    console.log('=== Test 1: Threshold passes ===');
    let evaluations = Eval.runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    let report = Eval.generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5 }
    });
    console.log('Passed:', report.passed);
    console.log('Thresholds:', report.thresholds);

    console.log('\n=== Test 2: Threshold fails ===');
    evaluations = Eval.runEvaluations({
      outputs: ['Hello', 'Wrong'],
      references: ['hello', 'world']
    });
    report = Eval.generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.9 }
    });
    console.log('Passed:', report.passed);
    console.log('Thresholds:', report.thresholds);

    console.log('\n=== Test 3: Metric with null score fails threshold ===');
    evaluations = Eval.runEvaluations({
      outputs: ['Hello'],
      references: []
    });
    report = Eval.generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: null,
      thresholds: { exact_match: 0.5 }
    });
    console.log('Passed:', report.passed);
    console.log('Thresholds:', report.thresholds);

    console.log('\n=== Test 4: Unknown metric throws error ===');
    evaluations = Eval.runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    try {
      report = Eval.generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        thresholds: { unknown_metric: 0.5 }
      });
      console.log('ERROR: Should have thrown');
    } catch (error) {
      console.log('Caught expected error:', error.message);
    }

    console.log('\n=== Test 5: Markdown output with thresholds ===');
    evaluations = Eval.runEvaluations({
      outputs: ['Hello', 'Wrong'],
      references: ['hello', 'world']
    });
    report = Eval.generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.9, toxicity: 0.8 }
    });
    const markdown = reporters.toMarkdown(report);
    console.log(markdown);

    console.log('\n=== Test 6: No thresholds specified ===');
    evaluations = Eval.runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    report = Eval.generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });
    console.log('Passed field exists:', 'passed' in report);
    console.log('Thresholds field exists:', 'thresholds' in report);
  });
});
ENDSCRIPT

